<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\TemplateVersion\Domain\ValueObject;

use Civi\Lughauth\Features\Document\Template\Domain\TemplateRef;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFail;

class TemplateVersionTemplateVO
{
    public static function from(TemplateVersionTemplateVO|TemplateRef $value): TemplateVersionTemplateVO
    {
        return self::fromUnsafe($value);
    }
    public static function tryFrom(mixed $value, ConstraintFailList $list): ?TemplateVersionTemplateVO
    {
        if ($value instanceof TemplateVersionTemplateVO) {
            // If is a ValueObject, its already validated... nothing to append
            return $value;
        } elseif (is_a($value, TemplateRef::class)) {
            return new TemplateVersionTemplateVO($value);
        } else {
            $list->add(new ConstraintFail('wrong_type', ['template'], [$value], ['TemplateRef']));
            return null;
        }
    }
    private static function fromUnsafe(mixed $value): TemplateVersionTemplateVO
    {
        if ($value instanceof TemplateVersionTemplateVO) {
            // If is a ValueObject, its already validated
            return $value;
        } else {
            // If is not a ValueObject, validation is need and exception throw
            $errorsList = new ConstraintFailList();
            $candidate = self::tryFrom($value, $errorsList);
            if ($errorsList->hasErrors()) {
                throw $errorsList->asConstraintException();
            }
            \assert($candidate instanceof TemplateVersionTemplateVO);
            return $candidate;
        }
    }
    /**
     * private constructor to avoid build a value without all the rule validations.
     */
    private function __construct(
        private readonly TemplateRef $template
    ) {
    }
    public function value(): TemplateRef
    {
        return $this->template;
    }
    public function equals(?TemplateVersionTemplateVO $other): bool
    {
        return $this->value()->uid() == $other?->value()?->uid();
    }
}
